package org.example.crosswords_backend.model;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.ManyToOne;

// Named AppUser because USER is a reserved word in MySQL.
@Entity
public class AppUser {

    // The user's identity everywhere in the backend (and the JWT's "sub"). Generated by the database and never changed,
    // so the username and the email can be changed later without breaking ownership of crosswords and submissions.
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private int id;

    // A display name, like a gamer tag. Unique, so two players never look the same in a list,
    // but not the identity: nothing points to it, so it can be changed later.
    @Column(nullable = false, unique = true)
    private String username;

    // What the user logs in with, so it must be unique. Stored in lower case, so "Erik@X.dk" and "erik@x.dk" are one user.
    @Column(nullable = false, unique = true)
    private String email;

    // A BCrypt hash. A plain-text password is never stored.
    private String passwordHash;

    // A foreign key to the role table. Nullable in the database only so users from before slice 31 can be moved
    // over with one UPDATE (see the natlog). The code always sets it: registration gives every new user PLAYER.
    @ManyToOne
    @JoinColumn(name = "role_id")
    private Role role;

    protected AppUser() {
        // required by JPA
    }

    public AppUser(String username, String email, String passwordHash, Role role) {
        this.username = username;
        this.email = email;
        this.passwordHash = passwordHash;
        this.role = role;
    }

    public int getId() {
        return id;
    }

    public String getUsername() {
        return username;
    }

    public String getEmail() {
        return email;
    }

    public String getPasswordHash() {
        return passwordHash;
    }

    public Role getRole() {
        return role;
    }
}
